#pragma once
#include "common.hpp"
using namespace compose;
struct Problem {Model m;State initial;V equilibrium,mass,msqrt,misqrt;Mat modes;V frequencies;double escale;std::string regime,motion;};
Problem problem(int N,std::string regime,std::string motion,double contrast=100){Problem p;p.regime=regime;p.motion=motion;auto&m=p.m;m.name="chain";m.count=N;m.dim=2;m.rigid=false;m.mass=V::Ones(N);m.length=V::Ones(N);m.stiffness=V::Constant(N,1000);m.gravity=V(2);m.gravity<<0,-9.81;
 double ratio=regime=="mass100"||regime=="both100"?contrast:1;for(int j=0;j<N;++j){m.mass[j]=2*(j%2?ratio:1)/(ratio+1);if(regime=="both100"||regime=="stiff100")m.stiffness[j]*=(j%2?1:contrast);}
 p.initial={V::Zero(2*N),V::Zero(2*N)};p.equilibrium=V::Zero(2*N);double downstream=m.mass.sum();V prev=V::Zero(2),eq=V::Zero(2);double large=motion=="large"?4:1;
 for(int j=0;j<N;++j){double r=1+downstream*9.81/m.stiffness[j];double angle=large*(.12*std::sin(3.141592653589793*(j+1)/(N+1))+.025*(j%2?1:-1));double stretch=large*(.025*(j%2?1:-1)+.035*std::sin(2.2*(j+1)));V e(2);e<<(r+stretch)*std::sin(angle),-(r+stretch)*std::cos(angle);prev+=e;eq[1]-=r;p.initial.x.segment<2>(2*j)=prev;p.equilibrium.segment<2>(2*j)=eq;p.initial.v[2*j]=large*(.2*std::sin(3.141592653589793*(j+1)/(N+1))+.08*(j%2?1:-1));p.initial.v[2*j+1]=large*.2*(j%2?1:-1);downstream-=m.mass[j];}
 p.mass=masses(m);p.msqrt=p.mass.cwiseSqrt();p.misqrt=p.msqrt.cwiseInverse();p.escale=std::max(1e-8,energy(m,p.initial)-minimum_energy(m));
 Mat K=Mat::Zero(2*N,2*N);for(int j=0;j<N;++j){V e=edge(m,p.equilibrium,j);double r=e.norm();V u=e/r;Mat A=m.stiffness[j]*(u*u.transpose()+(1-m.length[j]/r)*(Mat::Identity(2,2)-u*u.transpose()));K.block<2,2>(2*j,2*j)+=A;if(j){K.block<2,2>(2*j-2,2*j-2)+=A;K.block<2,2>(2*j,2*j-2)-=A;K.block<2,2>(2*j-2,2*j)-=A;}}
 Eigen::SelfAdjointEigenSolver<Mat> eig(p.misqrt.asDiagonal()*K*p.misqrt.asDiagonal());p.modes=eig.eigenvectors();p.frequencies=eig.eigenvalues().cwiseMax(0).cwiseSqrt();return p;}
struct ModeError {double relative=0,phase=0,high=0;};
ModeError mode_error(const Problem&p,const State&s,const State&reference){V a=p.modes.transpose()*p.msqrt.cwiseProduct(s.x-p.equilibrium),b=p.modes.transpose()*p.msqrt.cwiseProduct(s.v),ar=p.modes.transpose()*p.msqrt.cwiseProduct(reference.x-p.equilibrium),br=p.modes.transpose()*p.msqrt.cwiseProduct(reference.v);V A=p.frequencies.cwiseProduct(a),Ar=p.frequencies.cwiseProduct(ar);V er=.5*(Ar.array().square()+br.array().square()).matrix(),es=.5*(A.array().square()+b.array().square()).matrix();ModeError out;double total=std::max(1e-20,er.sum());out.relative=std::sqrt(((A-Ar).squaredNorm()+(b-br).squaredNorm())/(2*total));double weighted=0,weights=0;for(int k=0;k<a.size();++k)if(er[k]>1e-6*total){double phase=std::remainder(std::atan2(A[k],b[k])-std::atan2(Ar[k],br[k]),2*3.141592653589793);weighted+=er[k]*phase*phase;weights+=er[k];}out.phase=std::sqrt(weighted/std::max(1e-20,weights));int high=std::max(1,int(a.size()/4));out.high=std::abs(es.tail(high).sum()-er.tail(high).sum())/total;return out;}
